import {form,text,select as sel} from '../ui.mjs';
import {secureIndex} from '../core.mjs';
import {animeSVG} from './anime-core.mjs';
import {vectorResult} from './vector.mjs';
export function setupAnime(tool,mount,out){let timer;const fields=[{...text('name','Character name (optional)','Mika','text',true),required:false},sel('hair','Hairstyle',[['bob','Soft bob'],['spiky','Spiky'],['long','Long hair'],['ponytail','Side ponytail']],'bob'),text('hairColor','Hair color','#30334c','color'),sel('expression','Expression',[['bright','Bright eyes'],['happy','Happy smile'],['wink','Playful wink'],['serious','Determined']],'bright'),text('eyeColor','Eye color','#738e9b','color'),sel('outfit','Outfit',[['hoodie','Cozy hoodie'],['uniform','School uniform'],['jacket','Everyday jacket'],['tee','Star T-shirt']],'hoodie'),text('cloth','Outfit color','#9cbeb1','color'),sel('accessory','Accessory',[['none','No accessory'],['glasses','Glasses'],['headphones','Headphones'],['cat-ears','Cat ears'],['beanie','Beanie']],'none'),text('skin','Skin tone','#f4c7ad','color'),sel('background','Background',[['cream','Warm cream'],['lavender','Soft lavender'],['blue','Sky blue'],['transparent','Transparent cutout']],'cream')];fields.push(sel('exportScale','PNG resolution',[['1','900 × 1100'],['2','1800 × 2200'],['3','2700 × 3300']],'2'));const f=form(mount,fields,v=>{if(Array.from(v.name).length>32)throw Error('Keep the character name to 32 characters.');const scale=Number(v.exportScale);const filename=v.name.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'nepocore-anime-character';vectorResult(out,animeSVG(v),filename,{width:900*scale,height:1100*scale,label:'Your original character',details:[['PNG size',900*scale+' × '+1100*scale+' px'],['SVG','Editable vector artwork'],['Background',v.background]],note:'An original character builder using illustrated parts. PNG and SVG downloads include your chosen design; transparent mode leaves the character on a clear background.'});},{label:'Create character',note:'Try a hairstyle, a favorite color and a little personality. The preview updates as you change the controls.'});f.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(f.isConnected)f.requestSubmit();},120);});const random=document.createElement('button');random.type='button';random.className='btn secondary';random.textContent='Surprise me';f.querySelector('.form-actions').append(random);random.onclick=()=>{for(const name of ['hair','expression','outfit','accessory','background']){const el=f.elements[name];el.selectedIndex=secureIndex(el.options.length);}for(const name of ['hairColor','eyeColor','cloth'])f.elements[name].value=['#30334c','#865579','#708ca4','#9cbeb1','#bc7c71','#c29c57'][secureIndex(6)];f.requestSubmit();};const presets={Lavender:{hair:'long',hairColor:'#865579',eyeColor:'#706499',outfit:'hoodie',cloth:'#a89ac9',background:'lavender',accessory:'headphones'},Streetwear:{hair:'spiky',hairColor:'#30334c',eyeColor:'#46787a',outfit:'jacket',cloth:'#4e7a86',background:'blue',accessory:'beanie'},Campus:{hair:'bob',hairColor:'#805036',eyeColor:'#785744',outfit:'uniform',cloth:'#7a536c',background:'cream',accessory:'glasses'}};
 const preset=document.createElement('label');preset.className='field full';preset.innerHTML='<span>Style preset</span><select><option value="">Choose a preset</option>'+Object.keys(presets).map(name=>'<option>'+name+'</option>').join('')+'</select>';const choices=preset.querySelector('select');f.querySelector('.form-grid').prepend(preset);
 choices.addEventListener('change',()=>{const style=presets[choices.value];if(!style)return;for(const [key,value] of Object.entries(style))f.elements[key].value=value;choices.value='';clearTimeout(timer);f.requestSubmit();});
 return()=>clearTimeout(timer);}
